-- Some portions generated by Claude.

-- The sample's changes to AdventureWorks, applied once after the lorint PostgreSQL port has loaded
-- Microsoft's data (install.sh). Everything else is the published database, unchanged.
\set ON_ERROR_STOP on
BEGIN;

-- 0. Identity sequences. The port loads rows with their ids but leaves each serial column's sequence at 1,
-- so new rows would reuse ids. Move every sequence past its column's largest value.
DO $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT n.nspname AS schema_name, t.relname AS table_name, a.attname AS column_name,
               pg_get_serial_sequence(format('%I.%I', n.nspname, t.relname), a.attname) AS seq
        FROM pg_class t
        JOIN pg_namespace n ON n.oid = t.relnamespace
        JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped
        WHERE t.relkind = 'r'
          AND n.nspname IN ('person', 'humanresources', 'production', 'purchasing', 'sales')
          AND pg_get_serial_sequence(format('%I.%I', n.nspname, t.relname), a.attname) IS NOT NULL
    LOOP
        EXECUTE format('SELECT setval(%L, coalesce((SELECT max(%I) FROM %I.%I), 0) + 1, false)',
                       r.seq, r.column_name, r.schema_name, r.table_name);
    END LOOP;
END
$$;

-- 1. Foreign keys the schema implies but does not declare. A sales order line refers to its product and
-- special offer only through the composite key of sales.specialofferproduct. Declaring the two single
-- column keys lets init map a line's product and offer as relationships. The data already satisfies them.
ALTER TABLE sales.salesorderdetail
    ADD CONSTRAINT "FK_SalesOrderDetail_Product_ProductID"
        FOREIGN KEY (productid) REFERENCES production.product (productid),
    ADD CONSTRAINT "FK_SalesOrderDetail_SpecialOffer_SpecialOfferID"
        FOREIGN KEY (specialofferid) REFERENCES sales.specialoffer (specialofferid);

-- 2. Optimistic lock versions. Sales orders already have one (revisionnumber); a customer's email
-- address, the one contact detail order entry may change, gets its own.
ALTER TABLE person.emailaddress ADD COLUMN version integer NOT NULL DEFAULT 1;
COMMENT ON COLUMN person.emailaddress.version IS 'Optimistic lock version, added for the EclipseLink MCP sample.';

-- 3. Open orders. Every historical order is shipped (status 5), so order entry has nothing to work on.
-- Two in-process orders (status 1) per sales territory, each for a store customer that has ordered before,
-- with that customer's latest addresses and ship method and two products from that order, at today's list
-- price, no discount, no tax or freight.
CREATE TEMP TABLE seed_order AS
WITH latest AS (
    SELECT DISTINCT ON (h.customerid) h.*
    FROM sales.salesorderheader h
    JOIN sales.customer c ON c.customerid = h.customerid
    WHERE c.storeid IS NOT NULL AND h.territoryid IS NOT NULL
    ORDER BY h.customerid, h.orderdate DESC, h.salesorderid DESC
), ranked AS (
    SELECT l.*, row_number() OVER (PARTITION BY l.territoryid ORDER BY l.customerid) AS n
    FROM latest l
)
SELECT salesorderid AS template_id, customerid, salespersonid, territoryid, billtoaddressid,
       shiptoaddressid, shipmethodid, row_number() OVER (ORDER BY territoryid, n) AS seq
FROM ranked
WHERE n <= 2;

CREATE TEMP TABLE seed_line AS
SELECT s.seq, d.productid, d.orderqty, p.listprice
FROM seed_order s
JOIN LATERAL (
    SELECT d.productid, d.orderqty
    FROM sales.salesorderdetail d
    JOIN sales.specialofferproduct sop ON sop.specialofferid = 1 AND sop.productid = d.productid
    WHERE d.salesorderid = s.template_id
    ORDER BY d.salesorderdetailid
    LIMIT 2
) d ON true
JOIN production.product p ON p.productid = d.productid;

ALTER TABLE seed_order ADD COLUMN salesorderid integer;
UPDATE seed_order SET salesorderid = nextval('sales.salesorderheader_salesorderid_seq');

INSERT INTO sales.salesorderheader (salesorderid, revisionnumber, orderdate, duedate, shipdate, status,
        onlineorderflag, customerid, salespersonid, territoryid, billtoaddressid, shiptoaddressid,
        shipmethodid, subtotal, taxamt, freight, totaldue, comment)
SELECT s.salesorderid, 1, current_date - (s.seq % 5)::int, current_date - (s.seq % 5)::int + 12, NULL, 1,
       false, s.customerid, s.salespersonid, s.territoryid, s.billtoaddressid, s.shiptoaddressid,
       s.shipmethodid, t.subtotal, 0, 0, t.subtotal, 'Open order seeded for the EclipseLink MCP sample'
FROM seed_order s
JOIN (SELECT seq, sum(orderqty * listprice) AS subtotal FROM seed_line GROUP BY seq) t ON t.seq = s.seq;

INSERT INTO sales.salesorderdetail (salesorderid, orderqty, productid, specialofferid, unitprice,
        unitpricediscount)
SELECT s.salesorderid, l.orderqty, l.productid, 1, l.listprice, 0
FROM seed_line l
JOIN seed_order s ON s.seq = l.seq
ORDER BY s.salesorderid, l.productid;

-- 4. Database accounts. The MCP servers never connect as the owner.
-- mcp_reader: read-only, for the sales definition and for init.
CREATE ROLE mcp_reader LOGIN PASSWORD 'reader';
ALTER ROLE mcp_reader SET default_transaction_read_only = on;
-- mcp_order_entry: reads everything, and may change only what order entry's operations change.
CREATE ROLE mcp_order_entry LOGIN PASSWORD 'orderentry';

GRANT USAGE ON SCHEMA person, humanresources, production, purchasing, sales TO mcp_reader, mcp_order_entry;
GRANT SELECT ON ALL TABLES IN SCHEMA person, humanresources, production, purchasing, sales
    TO mcp_reader, mcp_order_entry;
GRANT INSERT, UPDATE ON sales.salesorderheader, sales.salesorderdetail TO mcp_order_entry;
GRANT UPDATE ON person.emailaddress TO mcp_order_entry;
GRANT USAGE ON SEQUENCE sales.salesorderheader_salesorderid_seq, sales.salesorderdetail_salesorderdetailid_seq
    TO mcp_order_entry;

COMMIT;

ANALYZE;
